class Translator:
    def __init__(self, language="nl"):
        self.language = language if language in LANGUAGES else "nl"
        self.index = tuple(LANGUAGES).index(self.language)

    def __call__(self, key, **values):
        return TEXT[key][self.index].format(**values)
